const int LDR = A0, LED = 9;
const int DARK = 300;                 // below this = night (check your values in the Serial Monitor)
const int DAYS_BETWEEN_WATERING = 3;

int days = 0;
bool night = false;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(LDR);
  Serial.println(light);

  // Hysteresis so a flickering lamp doesn't count as many sunrises.
  if (!night && light < DARK) night = true;
  else if (night && light > DARK + 100) { night = false; days++; }

  if (days >= DAYS_BETWEEN_WATERING) digitalWrite(LED, (millis() / 500) % 2);
  else digitalWrite(LED, LOW);
  delay(200);
}
